                    animate={{ left: [0, 100, 0] }}
                    transition={{
                        duration: 1,
                        repeat: Infinity,
                        times: [0, 0.5, 1],
                        ease: "easeInOut",
                    }}
                ></motion.div>
            )}
            <button onClick={() => setOpen(false)}>Disable animation</button>
        </div>
    )
}

